window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9431f29822a291a1"]={"versions": [{"id": "FIG-9431f29822a291a1", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion bei der Übertragung sporadischer LIN-Frames (Sporadic frame) innerhalb der AUTOSAR Classic Platform Schichtenarchitektur (Communication Stack). Dargestellt ist der synchrone Kontrollfluss zwischen der PDU Router-Schicht und der LIN-Interface-Schicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Beteiligte Entitäten:\n<ul class=\"fig-list\"><li>«module» PduR (PDU Router, Aufrufer)\n</li><li>«module» LinIf (LIN Interface, Empfänger/Dienstanbieter)\n</li></ul>\n</li><li>Schnittstellen und Operationen:\n<ul class=\"fig-list\"><li><code>LinIf_Transmit(LinTxPduId, PduInfoPtr) :Std_ReturnType</code>: Synchrone Service-Funktion des LIN-Interface zur Sendeanforderung.\n</li><li><code>CheckId()</code>: Interne Routine des <code>LinIf</code> zur Verifikation der übergebenen PDU-Kennung bzw. Zuordnung zum sporadischen Frame.\n</li><li><code>SetFlag()</code>: Interne Routine des <code>LinIf</code> zum Setzen des Übertragungs-/Update-Flags für den sporadischen Frame.\n</li></ul>\n</li><li>Rückgabepfeil: Gestrichelter Rückkehrpfeil von <code>LinIf</code> an <code>PduR</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das Modul <code>PduR</code> ruft synchron die Operation <code>LinIf_Transmit(LinTxPduId, PduInfoPtr)</code> am Modul <code>LinIf</code> auf.\n</li><li>Innerhalb des aktiven Ausführungsfokus im <code>LinIf</code> wird zunächst der interne Selbstaufruf <code>CheckId()</code> ausgeführt.\n</li><li>Anschließend führt <code>LinIf</code> den internen Selbstaufruf <code>SetFlag()</code> aus, um das Sende-Flag für den sporadischen Frame zu setzen.\n</li><li>Nach Abschluss der internen Verarbeitung erfolgt die Rückkehr des Kontrollflusses via gestricheltem Pfeil an <code>PduR</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Zeigt die protokollspezifische Behandlung sporadischer Frames: Anstelle einer unmittelbaren Busübertragung markiert der Aufruf von <code>LinIf_Transmit</code> die PDU intern (<code>CheckId</code>, <code>SetFlag</code>) für den nachfolgenden LIN-Scheduler.\n</li><li>Der Aufruf liefert synchron <code>Std_ReturnType</code> an den Aufrufer <code>PduR</code> zurück.\n</li><li>Implementierer des <code>LinIf</code> müssen sicherstellen, dass <code>LinTxPduId</code> validiert und das entsprechende Übertragungsflag für den nächsten Sendezyklus des Schedule-Tables atomar/konsistent gesetzt wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-44bc5a0b0774ea97", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion bei der Übertragung sporadischer LIN-Frames (Sporadic frame) innerhalb der AUTOSAR Classic Platform Schichtenarchitektur (Communication Stack). Dargestellt ist der synchrone Kontrollfluss zwischen einem übergeordneten LIN-Interface-Nutzer und der LIN-Interface-Schicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Beteiligte Entitäten:\n<ul class=\"fig-list\"><li>«module» LinIf User (generischer Nutzer des LIN-Interface, z. B. PduR, Aufrufer)\n</li><li>«module» LinIf (LIN Interface, Empfänger/Dienstanbieter)\n</li></ul>\n</li><li>Schnittstellen und Operationen:\n<ul class=\"fig-list\"><li><code>LinIf_Transmit(LinTxPduId, PduInfoPtr)</code>: Synchrone Service-Funktion des LIN-Interface zur Sendeanforderung.\n</li><li><code>CheckId()</code>: Interne Routine des <code>LinIf</code> zur Verifikation der übergebenen PDU-Kennung bzw. Zuordnung zum sporadischen Frame.\n</li><li><code>SetFlag()</code>: Interne Routine des <code>LinIf</code> zum Setzen des Übertragungs-/Update-Flags für den sporadischen Frame.\n</li></ul>\n</li><li>Rückgabepfeil: Gestrichelter Rückkehrpfeil von <code>LinIf</code> an <code>LinIf User</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das Modul <code>LinIf User</code> ruft synchron die Operation <code>LinIf_Transmit(LinTxPduId, PduInfoPtr)</code> am Modul <code>LinIf</code> auf.\n</li><li>Innerhalb des aktiven Ausführungsfokus im <code>LinIf</code> wird zunächst der interne Selbstaufruf <code>CheckId()</code> ausgeführt.\n</li><li>Anschließend führt <code>LinIf</code> den internen Selbstaufruf <code>SetFlag()</code> aus, um das Sende-Flag für den sporadischen Frame zu setzen.\n</li><li>Nach Abschluss der internen Verarbeitung erfolgt die Rückkehr des Kontrollflusses via gestricheltem Pfeil an <code>LinIf User</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Zeigt die protokollspezifische Behandlung sporadischer Frames: Anstelle einer unmittelbaren Busübertragung markiert der Aufruf von <code>LinIf_Transmit</code> die PDU intern (<code>CheckId</code>, <code>SetFlag</code>) für den nachfolgenden LIN-Scheduler.\n</li><li>Die Interaktion ist generalisiert auf beliebige Nutzer des LIN-Interface (<code>LinIf User</code>).\n</li><li>Implementierer des <code>LinIf</code> müssen sicherstellen, dass <code>LinTxPduId</code> validiert und das entsprechende Übertragungsflag für den nächsten Sendezyklus des Schedule-Tables atomar/konsistent gesetzt wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cf14035b85903efa", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion bei der Übertragung sporadischer LIN-Frames (Sporadic frame) innerhalb der AUTOSAR Classic Platform Schichtenarchitektur (Communication Stack). Dargestellt ist der synchrone Kontrollfluss zwischen einem übergeordneten LIN-Interface-Nutzer und der LIN-Interface-Schicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Beteiligte Entitäten:\n<ul class=\"fig-list\"><li>«module» LinIf User (generischer Nutzer des LIN-Interface, z. B. PduR, Aufrufer)\n</li><li>«module» LinIf (LIN Interface, Empfänger/Dienstanbieter)\n</li></ul>\n</li><li>Schnittstellen und Operationen:\n<ul class=\"fig-list\"><li><code>LinIf_Transmit(LinTxPduId, PduInfoPtr)</code>: Synchrone Service-Funktion des LIN-Interface zur Sendeanforderung.\n</li><li><code>CheckId()</code>: Interne Routine des <code>LinIf</code> zur Verifikation der übergebenen PDU-Kennung bzw. Zuordnung zum sporadischen Frame.\n</li><li><code>SetFlag()</code>: Interne Routine des <code>LinIf</code> zum Setzen des Übertragungs-/Update-Flags für den sporadischen Frame.\n</li></ul>\n</li><li>Rückgabepfeil: Gestrichelter Rückkehrpfeil von <code>LinIf</code> an <code>LinIf User</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das Modul <code>LinIf User</code> ruft synchron die Operation <code>LinIf_Transmit(LinTxPduId, PduInfoPtr)</code> am Modul <code>LinIf</code> auf.\n</li><li>Innerhalb des aktiven Ausführungsfokus im <code>LinIf</code> wird zunächst der interne Selbstaufruf <code>CheckId()</code> ausgeführt.\n</li><li>Anschließend führt <code>LinIf</code> den internen Selbstaufruf <code>SetFlag()</code> aus, um das Sende-Flag für den sporadischen Frame zu setzen.\n</li><li>Nach Abschluss der internen Verarbeitung erfolgt die Rückkehr des Kontrollflusses via gestricheltem Pfeil an <code>LinIf User</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Zeigt die protokollspezifische Behandlung sporadischer Frames: Anstelle einer unmittelbaren Busübertragung markiert der Aufruf von <code>LinIf_Transmit</code> die PDU intern (<code>CheckId</code>, <code>SetFlag</code>) für den nachfolgenden LIN-Scheduler.\n</li><li>Die Interaktion ist generalisiert auf beliebige Nutzer des LIN-Interface (<code>LinIf User</code>).\n</li><li>Implementierer des <code>LinIf</code> müssen sicherstellen, dass <code>LinTxPduId</code> validiert und das entsprechende Übertragungsflag für den nächsten Sendezyklus des Schedule-Tables atomar/konsistent gesetzt wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c191f3360eccf2b2", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion bei der Übertragung sporadischer LIN-Frames (Sporadic frame) innerhalb der AUTOSAR Classic Platform Schichtenarchitektur (Communication Stack). Dargestellt ist der synchrone Kontrollfluss zwischen einem übergeordneten LIN-Interface-Nutzer und der LIN-Interface-Schicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Beteiligte Entitäten:\n<ul class=\"fig-list\"><li>«module» LinIf User (generischer Nutzer des LIN-Interface, z. B. PduR, Aufrufer)\n</li><li>«module» LinIf (LIN Interface, Empfänger/Dienstanbieter)\n</li></ul>\n</li><li>Schnittstellen und Operationen:\n<ul class=\"fig-list\"><li><code>LinIf_Transmit(LinTxPduId, PduInfoPtr)</code>: Synchrone Service-Funktion des LIN-Interface zur Sendeanforderung.\n</li><li><code>CheckId()</code>: Interne Routine des <code>LinIf</code> zur Verifikation der übergebenen PDU-Kennung bzw. Zuordnung zum sporadischen Frame.\n</li><li><code>SetFlag()</code>: Interne Routine des <code>LinIf</code> zum Setzen des Übertragungs-/Update-Flags für den sporadischen Frame.\n</li></ul>\n</li><li>Rückgabepfeil: Gestrichelter Rückkehrpfeil von <code>LinIf</code> an <code>LinIf User</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Das Modul <code>LinIf User</code> ruft synchron die Operation <code>LinIf_Transmit(LinTxPduId, PduInfoPtr)</code> am Modul <code>LinIf</code> auf.\n</li><li>Innerhalb des aktiven Ausführungsfokus im <code>LinIf</code> wird zunächst der interne Selbstaufruf <code>CheckId()</code> ausgeführt.\n</li><li>Anschließend führt <code>LinIf</code> den internen Selbstaufruf <code>SetFlag()</code> aus, um das Sende-Flag für den sporadischen Frame zu setzen.\n</li><li>Nach Abschluss der internen Verarbeitung erfolgt die Rückkehr des Kontrollflusses via gestricheltem Pfeil an <code>LinIf User</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Zeigt die protokollspezifische Behandlung sporadischer Frames: Anstelle einer unmittelbaren Busübertragung markiert der Aufruf von <code>LinIf_Transmit</code> die PDU intern (<code>CheckId</code>, <code>SetFlag</code>) für den nachfolgenden LIN-Scheduler.\n</li><li>Die Interaktion ist generalisiert auf beliebige Nutzer des LIN-Interface (<code>LinIf User</code>).\n</li><li>Implementierer des <code>LinIf</code> müssen sicherstellen, dass <code>LinTxPduId</code> validiert und das entsprechende Übertragungsflag für den nächsten Sendezyklus des Schedule-Tables atomar/konsistent gesetzt wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9431f29822a291a1", "to": "FIG-44bc5a0b0774ea97", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Aufrufendes Modul: Der Interaktionspartner von <code>LinIf</code> wurde von <code>PduR</code> auf die generischere Rolle <code>LinIf User</code> geändert.\n</li><li>Funktionsaufruf: Bei der Schnittstellenfunktion <code>LinIf_Transmit(LinTxPduId, PduInfoPtr)</code> entfällt die explizite Rückgabetypangabe <code>:Std_ReturnType</code> an der Aufrufkante.\n</li></ul>"}, {"from": "FIG-44bc5a0b0774ea97", "to": "FIG-cf14035b85903efa", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cf14035b85903efa", "to": "FIG-c191f3360eccf2b2", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
